#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size();
    // left[i] / right[i]: length of the smooth run ending / starting at i.
    vector<long long> left(n, 1), right(n, 1);
    for (int i = 1; i < n; i++)
        if (abs(s[i] - s[i - 1]) <= 1) left[i] = left[i - 1] + 1;
    for (int i = n - 2; i >= 0; i--)
        if (abs(s[i] - s[i + 1]) <= 1) right[i] = right[i + 1] + 1;
    long long baseline = accumulate(left.begin(), left.end(), 0LL), answer = baseline;
    for (int i = 0; i < n; i++) {
        long long old = left[i] * right[i]; // smooth substrings that contain i
        for (int c = 'a'; c <= 'z'; c++) {
            long long l = i > 0 && abs(c - s[i - 1]) <= 1 ? left[i - 1] : 0;
            long long r = i + 1 < n && abs(c - s[i + 1]) <= 1 ? right[i + 1] : 0;
            answer = max(answer, baseline - old + (l + 1) * (r + 1));
        }
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static String next() throws IOException {
        int c = skipSpaces();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String text = next();
        int n = text.length();
        char[] s = text.toCharArray();
        // left[i] / right[i]: length of the smooth run ending / starting at i.
        long[] left = new long[n], right = new long[n];
        Arrays.fill(left, 1);
        Arrays.fill(right, 1);
        for (int i = 1; i < n; i++)
            if (Math.abs(s[i] - s[i - 1]) <= 1) left[i] = left[i - 1] + 1;
        for (int i = n - 2; i >= 0; i--)
            if (Math.abs(s[i] - s[i + 1]) <= 1) right[i] = right[i + 1] + 1;
        long baseline = 0;
        for (long v : left) baseline += v;
        long answer = baseline;
        for (int i = 0; i < n; i++) {
            long old = left[i] * right[i]; // smooth substrings that contain i
            for (int c = 'a'; c <= 'z'; c++) {
                long l = i > 0 && Math.abs(c - s[i - 1]) <= 1 ? left[i - 1] : 0;
                long r = i + 1 < n && Math.abs(c - s[i + 1]) <= 1 ? right[i + 1] : 0;
                answer = Math.max(answer, baseline - old + (l + 1) * (r + 1));
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func near(x, y byte) bool {
	return x+1 >= y && y+1 >= x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := next()
	n := len(s)
	// left[i] / right[i]: length of the smooth run ending / starting at i.
	left, right := make([]int, n), make([]int, n)
	for i := range left {
		left[i], right[i] = 1, 1
	}
	for i := 1; i < n; i++ {
		if near(s[i], s[i-1]) {
			left[i] = left[i-1] + 1
		}
	}
	for i := n - 2; i >= 0; i-- {
		if near(s[i], s[i+1]) {
			right[i] = right[i+1] + 1
		}
	}
	baseline := 0
	for _, v := range left {
		baseline += v
	}
	answer := baseline
	for i := 0; i < n; i++ {
		old := left[i] * right[i] // smooth substrings that contain i
		for c := byte('a'); c <= 'z'; c++ {
			l, r := 0, 0
			if i > 0 && near(c, s[i-1]) {
				l = left[i-1]
			}
			if i+1 < n && near(c, s[i+1]) {
				r = right[i+1]
			}
			answer = max(answer, baseline-old+(l+1)*(r+1))
		}
	}
	os.Stdout.WriteString(strconv.Itoa(answer) + "\n")
}
